<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Infrastructure\Driven;

use Override;
use Handlebars\Handlebars;
use Handlebars\Loader;
use Handlebars\Loader\StringLoader;
use Civi\Lughauth\Features\Document\Rendering\Domain\RenderedAsset;
use Civi\Lughauth\Features\Document\Rendering\Domain\RenderedTemplate;
use Civi\Lughauth\Features\Document\Rendering\Domain\TemplateOutputFormat;
use Civi\Lughauth\Features\Document\Rendering\Domain\TemplateRenderRequest;
use Civi\Lughauth\Features\Document\Rendering\Domain\Gateway\TemplateRenderGateway;

/**
 * Rendering engine adapter backed by Handlebars (salesforce/handlebars-php).
 *
 * Receives pre-resolved raw content strings, snippets and merged variables from the use case
 * and performs purely technical string substitution. Contains no domain logic.
 *
 * Syntax supported in templates:
 *   {{variable}}        — HTML-escaped variable substitution
 *   {{object.field}}    — nested property access (dotted keys expanded to nested arrays)
 *   {{{rawHtml}}}       — unescaped HTML injection
 *   {{>HEADER}}         — snippet partial (resolved from the snippets map)
 */
class HandlebarsTemplateRenderAdapter implements TemplateRenderGateway
{
    #[Override]
    public function render(TemplateRenderRequest $request): RenderedTemplate
    {
        $engine  = $this->buildEngine($request->snippets());
        $context = $this->toNestedMap($request->variables());

        $subject  = null !== $request->getSubject()
            ? $engine->render($request->getSubject(), $context)
            : null;

        $html = $engine->render($request->htmlContent(), $context);

        $text = null !== $request->getTextContent()
            ? $engine->render($request->getTextContent(), $context)
            : null;

        $assets = $request->assets();

        if (TemplateOutputFormat::HTML_EMBEDDED === $request->outputFormat()) {
            $html = $this->inlineCssAssets($html, $assets);
        }

        return new RenderedTemplate(
            htmlContent: $html,
            subject: $subject,
            textContent: $text,
            assets: $assets,
        );
    }

    // ---------------------------------------------------------------------------
    // Private helpers
    // ---------------------------------------------------------------------------

    /**
     * Builds a Handlebars instance whose partial loader resolves {{>partialName}}
     * against the preloaded snippets map.
     *
     * @param array<string, string> $snippets
     */
    private function buildEngine(array $snippets): Handlebars
    {
        $partialsLoader = new class($snippets) implements Loader {
            /** @param array<string, string> $snippets */
            public function __construct(private readonly array $snippets)
            {
            }

            public function load($name): string
            {
                return $this->snippets[(string) $name] ?? '';
            }
        };

        return new Handlebars([
            'loader'          => new StringLoader(),
            'partials_loader' => $partialsLoader,
        ]);
    }

    /**
     * Inlines all CSS assets from $assets into the <head> of the given HTML as
     * <style> blocks. Each inlined asset is replaced with a copy that has embedded = true
     * so callers know it no longer needs to be linked externally.
     *
     * If the HTML has no </head> tag the style block is prepended to the document.
     *
     * @param RenderedAsset[] $assets
     */
    private function inlineCssAssets(string $html, array &$assets): string
    {
        $cssIndexes = [];
        foreach ($assets as $i => $asset) {
            if (
                strtolower($asset->contentType()) === 'text/css'
                && !$asset->isEmbedded()
                && trim($asset->content()) !== ''
            ) {
                $cssIndexes[] = $i;
            }
        }

        if (empty($cssIndexes)) {
            return $html;
        }

        $styleBlocks = '';
        foreach ($cssIndexes as $i) {
            $styleBlocks .= '<style>' . $assets[$i]->content() . '</style>' . "\n";
            $assets[$i]   = $assets[$i]->withEmbedded(true);
        }

        $headClose = strpos($html, '</head>');
        if ($headClose !== false) {
            return substr($html, 0, $headClose) . $styleBlocks . substr($html, $headClose);
        }

        return $styleBlocks . $html;
    }

    /**
     * Expands flat dotted-key entries (e.g. "user.name" => "Alice") into nested arrays
     * (["user" => ["name" => "Alice"]]) so Handlebars resolves {{user.name}} correctly.
     *
     * @param  array<string, string> $flat
     * @return array<string, mixed>
     */
    private function toNestedMap(array $flat): array
    {
        $root = [];

        foreach ($flat as $key => $value) {
            $parts   = explode('.', $key);
            $current = &$root;

            foreach (array_slice($parts, 0, -1) as $part) {
                if (!isset($current[$part]) || !is_array($current[$part])) {
                    $current[$part] = [];
                }
                $current = &$current[$part];
            }

            $current[end($parts)] = $value;
        }

        return $root;
    }
}
